3568	    // Opens the panel the way Home and the header do: through the shell, which
3569	    // gives it the whole window.
3570	    void live_show(PrinterSetup::ConversationMode mode, const std::string& printer)
3571	    {
3572	        // The shell refuses to open a chat while one is open, and a close
3573	        // finishes on a later event turn (PrinterPanel::close). So an open
3574	        // chat is closed first, as the person would, and the next is opened
3575	        // once that close has run. Each open step also waits for the panel to
3576	        // show, so it never proceeds on the session being closed.
3577	        const auto open = [mode, printer] {
3578	            installed_shell()->open_printer_conversation(mode == PrinterSetup::ConversationMode::Add ? std::string() : printer,
3579	                                                         mode == PrinterSetup::ConversationMode::Connect);
3580	        };
3581	        // Queued on the panel, where PrinterPanel::close queues its own
3582	        // finish, so the open runs after any close still waiting, this one's
3583	        // or an earlier step's. (The app's queue has no order with it.)
3584	        if (live_panel()->IsShown())
3585	            live_panel()->close();
3586	        live_panel()->CallAfter(open);
3587	    }
