3676	    // Settled: nothing streaming, no tool mid-run, and the model has had its
3677	    // last word.
3678	    bool live_settled() const
3679	    {
3680	        Agent::AgentHost* host = live_panel()->host();
3681	        // A panel that closed has nothing more to say; the step's own
3682	        // checks see what closed it.
3683	        if (host == nullptr)
3684	            return true;
3685	        if (host->stream_active())
3686	            return false;
3687	        const auto& activities = live_activities();
3688	        if (!activities.empty()) {
3689	            const Agent::ToolState state = activities.back().state;
3690	            if (state == Agent::ToolState::Running)
3691	                return false;
3692	        }
3693	        // A finished reply with no words is settled too; live_print_new
3694	        // says so, rather than the run waiting on it forever.
3695	        const auto messages = live_messages();
3696	        return !messages.empty() && messages.back().role == Agent::MessageRole::Assistant &&
3697	               messages.back().state == Agent::MessageState::Complete;
3698	    }
