3758	    void run_live_steps()
3759	    {
3760	        if (m_live_steps.empty()) {
3761	            finish_printer_live();
3762	            return;
3763	        }
3764	        LiveStep step = std::move(m_live_steps.front());
3765	        m_live_steps.pop_front();
3766	        std::cerr << "HARNESS LIVE -- " << step.label << '\n';
3767	        m_live_step = step.label;
3768	        step.act();
3769	        auto ready = step.ready ? step.ready : [this] { return live_settled(); };
3770	        wait_until(
3771	            ready, "live_" + step.label,
3772	            [self = shared_from_this(), check = step.check] {
3773	                self->live_print_new();
3774	                if (check)
3775	                    check();
3776	                self->run_live_steps();
3777	            },
3778	            [this, ticks = std::make_shared<int>(0)] {
3779	                if (++*ticks % 300 != 0 || live_panel()->host() == nullptr)
3780	                    return;
3781	                const auto messages = live_messages();
3782	                std::cerr << "HARNESS LIVE   waiting: stream=" << live_panel()->host()->stream_active()
3783	                          << " messages=" << messages.size() << " tools=" << live_activities().size();
3784	                if (!messages.empty())
3785	                    std::cerr << " last role=" << static_cast<int>(messages.back().role)
3786	                              << " state=" << static_cast<int>(messages.back().state) << " text=" << messages.back().text.size()
3787	                              << (messages.back().error ? " error=" + messages.back().error->code + " " + messages.back().error->message : "");
3788	                std::cerr << '\n';
3789	            });
3790	    }
