5087	    // Opens the panel on `printer` with a model that answers the first
5088	    // message by calling `tool`, sends that message, and returns the call.
5089	    const Agent::ToolActivity* call_in_panel(const std::string& printer, const std::string& tool, const nlohmann::json& arguments,
5090	                                             const std::string& name)
5091	    {
5092	        using namespace std::chrono_literals;
5093	        PrinterSetup::PrinterPanel* panel = installed_shell()->printer_panel();
5094	        panel->open(PrinterSetup::ConversationMode::Connect, printer);
5095	        const bool loaded = wait_for([panel] {
5096	            return panel->host() != nullptr && panel->host()->handshake_complete() && panel->instructions_ready();
5097	        }, 60s);
5098	        check(loaded, name + "_page_loaded");
5099	        if (!loaded)
5100	            return nullptr;
5101	        Agent::AgentHost* host = panel->host();
5102	        host->set_agent(std::make_unique<ToolCallingAgent>(tool, arguments), Agent::AgentAvailability::Ready);
5103	        static int next = 0;
5104	        host->on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
5105	                                             {"version", Agent::Protocol::kVersion},
5106	                                             {"id", "call-" + std::to_string(++next)},
5107	                                             {"type", "user_message"},
5108	                                             {"payload", {{"clientMessageId", "call-c-" + std::to_string(next)}, {"text", "go on"}}}}
5109	                                  .dump());
5110	        const auto call = [host, tool]() -> const Agent::ToolActivity* {
5111	            for (const auto& activity : host->tools().activities())
5112	                if (activity.tool == tool)
5113	                    return &activity;
5114	            return nullptr;
5115	        };
5116	        const bool made = wait_for([&] {
5117	            const auto* activity = call();
5118	            return activity != nullptr && activity->state != Agent::ToolState::Running;
5119	        }, 10s);
5120	        check(made, name + "_tool_called");
5121	        return made ? call() : nullptr;
5122	    }
