5124	    // The panel closed while its printer was still being checked, and the
5125	    // host answers afterwards: nothing is saved, then or when the panel next
5126	    // looks at the connection.
5127	    void verify_panel_close_drops_a_waiting_connection(const std::string& saved)
5128	    {
5129	        using namespace std::chrono_literals;
5130	        PrinterSetup::PrinterPanel* panel = installed_shell()->printer_panel();
5131	        StandInHost                 late(2000ms, /*answer=*/true);
5132	        const Agent::ToolActivity*  card = call_in_panel(kAddedPrinter, "printer_connect",
5133	                                                         nlohmann::json{{"hostType", "moonraker"}, {"address", late.address()}},
5134	                                                         "panel_close_fixture");
5135	        const auto request = panel->session_json().value("credentialRequest", nlohmann::json::object());
5136	        check(card != nullptr && request.value("actionId", "") == card->action_id,
5137	              "panel_close_fixture_credential_requested");
5138	        if (card == nullptr)
5139	            return;
5140	        const std::string action = card->action_id;
5141	        panel->host()->on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
5142	                                                      {"version", Agent::Protocol::kVersion},
5143	                                                      {"id", "close-decision"},
5144	                                                      {"type", "printer_action"},
5145	                                                      {"payload", {{"action", "connect"}, {"actionId", action}, {"credential", ""}}}}
5146	                                           .dump());
5147	        check(wait_for([&] { return late.requests() == 1; }, 10s), "panel_close_fixture_is_connecting");
5148	        panel->close();
5149	        wait_for([] { return false; }, 3000ms);
5150	        check(!panel->IsShown() && late.requests() == 1, "panel_close_mid_test_closes");
5151	
5152	        // Opened again: the status the model reads does not bring the old
5153	        // answer back.
5154	        const Agent::ToolActivity* status = call_in_panel(kAddedPrinter, "printer_connection_status", nlohmann::json::object(),
5155	                                                          "panel_reopen");
5156	        check(status != nullptr && status->state == Agent::ToolState::Succeeded &&
5157	                  nlohmann::json::parse(status->result_json).value("state", "") != "verified",
5158	              "panel_reopen_does_not_read_the_old_answer");
5159	        check(printer_profile(kAddedPrinter)->config.opt_string("print_host") == saved, "panel_close_mid_test_saves_nothing");
5160	        panel->close();
5161	        wait_for([panel] { return !panel->IsShown(); }, 5s);
5162	    }
